<template><BioNexusDialog ref="dialog" size="wide" dialog-class="payment-method-dialog" :prevent-close="saving" :kicker="mode==='create'?'Nuevo registro':'Editar registro'" :title="mode==='create'?'Crear forma de pago':'Editar forma de pago'" @close="resetValidation"><section class="payment-method-body"><BioNexusFormField label="Descripción" field-id="type-payment-description" :error="descriptionError" required><input id="type-payment-description" ref="firstInput" v-model.trim="draft.description" class="bio-nexus-field" maxlength="100" @input="syncDirty"></BioNexusFormField><fieldset class="payment-section"><legend>Monedas disponibles</legend><label v-for="currency in currencyOptions" :key="currency.id" class="currency-row"><input v-model="draft.currencyIds" type="checkbox" :value="currency.id" @change="syncCurrency"><span><strong>{{currency.code}}</strong><small>{{currency.name}}</small></span><input v-model.number="draft.defaultCurrencyId" type="radio" name="default-payment-currency" :value="currency.id" :disabled="!draft.currencyIds.includes(currency.id)" @change="syncDirty"><b>Predeterminada</b></label><p v-if="currencyError" class="field-error">{{currencyError}}</p></fieldset><section class="payment-section fields-section"><header><div><strong>Campos adicionales</strong><small>Define la información complementaria que deberá completar el usuario al registrar un pago, por ejemplo referencia, banco, teléfono o fecha.</small></div><button type="button" class="bio-nexus-action bio-nexus-action-secondary" :disabled="saving" @click="addField"><BioNexusActionIcon action="create"/>Agregar campo</button></header><p v-if="!draft.fields.length" class="bio-nexus-empty-state">Esta forma de pago no solicita datos adicionales.</p><article v-for="(field,index) in draft.fields" :key="field.clientKey" class="field-card"><span class="order-number">{{index+1}}</span><div class="field-grid"><BioNexusFormField label="Etiqueta" :field-id="'field-label-'+index" :error="fieldError(index,'label')" help="Nombre que verá el usuario durante el ingreso del pago." required><input :id="'field-label-'+index" v-model.trim="field.label" class="bio-nexus-field" maxlength="100" @input="syncDirty"></BioNexusFormField><BioNexusFormField label="Tipo" :field-id="'field-type-'+index" help="Define el tipo de información que deberá completar el usuario." required><select :id="'field-type-'+index" v-model="field.fieldType" class="bio-nexus-field" @change="syncDirty"><option v-for="type in fieldTypes" :key="type.value" :value="type.value">{{type.label}}</option></select></BioNexusFormField><BioNexusFormField label="Ayuda" :field-id="'field-help-'+index" help="Instrucción breve que aparecerá debajo del campo."><input :id="'field-help-'+index" v-model.trim="field.helpText" class="bio-nexus-field" maxlength="255" @input="syncDirty"></BioNexusFormField><label class="required-check"><input v-model="field.isRequired" type="checkbox" @change="syncDirty"> Obligatorio</label></div><div class="field-actions"><button type="button" :disabled="index===0||saving" title="Subir" @click="moveField(index,-1)">↑</button><button type="button" :disabled="index===draft.fields.length-1||saving" title="Bajar" @click="moveField(index,1)">↓</button><button type="button" class="remove" :disabled="saving" title="Quitar campo" aria-label="Quitar campo" @click="removeField(index)"><BioNexusActionIcon action="delete"/></button></div></article><p v-if="fieldsError" class="field-error">{{fieldsError}}</p></section><div v-if="errorMessage" class="bio-nexus-message bio-nexus-message-error">{{errorMessage}}</div></section><template #footer><button class="bio-nexus-action bio-nexus-action-secondary" :disabled="saving" @click="close"><BioNexusActionIcon action="cancel"/>Cancelar</button><button class="bio-nexus-action bio-nexus-action-primary" :disabled="submitDisabled" @click="submit"><BioNexusActionIcon action="save"/>{{saving?'Guardando...':mode==='create'?'Crear':'Guardar'}}</button></template></BioNexusDialog></template>
<script setup>import{computed,nextTick,reactive,ref}from'vue';import BioNexusDialog from'@/components/ui/BioNexusDialog.vue';import BioNexusFormField from'@/components/ui/BioNexusFormField.vue';import BioNexusActionIcon from'@/components/ui/BioNexusActionIcon.vue';const props=defineProps({saving:Boolean,canCreate:Boolean,canUpdate:Boolean,currencyOptions:{type:Array,default:()=>[]}}),emit=defineEmits(['submit']),dialog=ref(null),firstInput=ref(null),mode=ref('create'),current=ref(null),attempted=ref(false),errorMessage=ref(''),original=ref(''),sequence=ref(0),draft=reactive({description:'',currencyIds:[],defaultCurrencyId:0,fields:[]});const fieldTypes=[{value:'text',label:'Texto'},{value:'number',label:'Número'},{value:'date',label:'Fecha'},{value:'phone',label:'Teléfono'},{value:'reference',label:'Referencia'},{value:'bank',label:'Banco'},{value:'boolean',label:'Sí / No'}];const technicalCode=()=>`PAYMENT_${Date.now().toString(36).toUpperCase()}`;const fieldCode=(label,index)=>String(label||`campo-${index+1}`).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,42)||`campo-${index+1}`;const values=computed(()=>({code:mode.value==='create'?technicalCode():current.value?.code,description:draft.description.trim(),displayOrder:mode.value==='create'?0:Number(current.value?.displayOrder)||0,currencyIds:[...new Set(draft.currencyIds.map(Number))],defaultCurrencyId:Number(draft.defaultCurrencyId)||0,fields:draft.fields.map((field,index)=>({code:field.code||fieldCode(field.label,index),label:field.label.trim(),fieldType:field.fieldType,isRequired:Boolean(field.isRequired),minLength:field.minLength??null,maxLength:field.maxLength??null,inputMask:field.inputMask||null,validationPattern:field.validationPattern||null,helpText:field.helpText.trim()||null,catalogSource:field.fieldType==='bank'?'banks':null,isActive:field.isActive!==false}))}));const signature=computed(()=>JSON.stringify({...values.value,code:mode.value==='create'?'NEW':values.value.code})),descriptionError=computed(()=>attempted.value&&!draft.description.trim()?'La descripción es obligatoria.':''),currencyError=computed(()=>!attempted.value?'':!draft.currencyIds.length?'Selecciona al menos una moneda.':!draft.currencyIds.includes(draft.defaultCurrencyId)?'Selecciona una moneda predeterminada válida.':''),fieldsError=computed(()=>attempted.value&&draft.fields.some(x=>!x.label.trim())?'Completa la etiqueta de todos los campos.':''),submitDisabled=computed(()=>props.saving||(mode.value==='create'?(!props.canCreate||!draft.description.trim()||!draft.currencyIds.length||!draft.currencyIds.includes(draft.defaultCurrencyId)||draft.fields.some(x=>!x.label.trim())):(!props.canUpdate||signature.value===original.value)));function makeField(value={}){return{clientKey:++sequence.value,id:Number(value.id)||0,code:value.code||'',label:value.label||'',fieldType:value.fieldType||'text',isRequired:Boolean(value.isRequired),minLength:value.minLength??null,maxLength:value.maxLength??null,inputMask:value.inputMask||'',validationPattern:value.validationPattern||'',helpText:value.helpText||'',isActive:value.isActive!==false}}function assign(row){draft.description=row?.description||'';draft.currencyIds=[...(row?.currencyIds||[])];draft.defaultCurrencyId=Number(row?.defaultCurrencyId)||0;draft.fields=(row?.fields||[]).map(makeField)}async function show(){original.value=signature.value;await dialog.value?.open();await nextTick();original.value=signature.value;firstInput.value?.focus()}async function openCreate(){mode.value='create';current.value=null;assign(null);attempted.value=false;errorMessage.value='';original.value='';await show()}async function openEdit(row){mode.value='edit';current.value=row;assign(row);attempted.value=false;errorMessage.value='';await show()}function addField(){draft.fields.push(makeField());syncDirty()}function removeField(index){draft.fields.splice(index,1);syncDirty()}function moveField(index,delta){const target=index+delta;if(target<0||target>=draft.fields.length)return;const[row]=draft.fields.splice(index,1);draft.fields.splice(target,0,row);syncDirty()}function syncCurrency(){if(draft.currencyIds.length&&!draft.currencyIds.includes(draft.defaultCurrencyId))draft.defaultCurrencyId=Number(draft.currencyIds[0]);syncDirty()}function syncDirty(){}function fieldError(index,name){return attempted.value&&name==='label'&&!draft.fields[index]?.label.trim()?'La etiqueta es obligatoria.':''}function submit(){attempted.value=true;if(descriptionError.value||currencyError.value||fieldsError.value)return;if(submitDisabled.value)return;emit('submit',{mode:mode.value,record:current.value,values:values.value})}function close(){dialog.value?.close()}function resetValidation(){attempted.value=false}defineExpose({openCreate,openEdit,close,setError:value=>errorMessage.value=String(value||''),clearError:()=>errorMessage.value=''})</script>
<style scoped>.payment-method-body{display:grid;gap:12px;font:400 13px var(--bio-nexus-font-family,Inter,Roboto,Arial,sans-serif)}.payment-section{display:grid;gap:8px;margin:0;padding:12px;border:1px solid var(--bio-nexus-color-border);border-radius:var(--bio-nexus-radius-md)}.payment-section legend,.fields-section header strong{font-size:14px;font-weight:700}.currency-row{display:grid;grid-template-columns:18px minmax(0,1fr) 18px auto;align-items:center;gap:8px}.currency-row span{display:grid}.currency-row small,.fields-section header small{color:var(--bio-nexus-color-text-muted)}.fields-section header{display:flex;align-items:center;justify-content:space-between}.fields-section header div{display:grid}.field-card{display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:9px;align-items:start;padding:9px;border:1px solid var(--bio-nexus-color-border);border-radius:8px;background:var(--bio-nexus-color-surface-soft)}.order-number{display:grid;place-items:center;width:32px;height:32px;margin:14px auto 0;border:1px solid var(--bio-nexus-color-border-strong);border-radius:50%;font-weight:700}.field-grid{display:grid;grid-template-columns:1.2fr .8fr 1.2fr auto;gap:8px;align-items:start}.field-grid :deep(.bio-nexus-field-group){grid-template-rows:auto 42px minmax(32px,auto);align-content:start}.field-grid :deep(.bio-nexus-field-help){min-height:32px;line-height:16px}.required-check{align-self:start;margin-top:9px}.required-check{display:flex;align-items:center;gap:6px;min-height:42px}.field-actions{display:flex;align-items:center;gap:4px;margin-top:13px}.field-actions button{min-width:34px;height:34px;border:1px solid var(--bio-nexus-color-border);border-radius:50%;background:var(--bio-nexus-color-surface);color:var(--bio-nexus-color-primary)}.field-actions .remove{display:grid;place-items:center;width:34px;min-width:34px;padding:0;border-radius:50%;color:var(--bio-nexus-color-danger)}.field-actions .remove :deep(.bio-nexus-icon),.field-actions .remove :deep(.material-symbols-rounded){width:18px;height:18px;font-size:18px}.field-error{margin:0;color:var(--bio-nexus-color-danger);font-size:12px}@media(max-width:900px){.field-grid{grid-template-columns:1fr 1fr}.field-card{grid-template-columns:34px 1fr}.field-actions{grid-column:2}}@media(max-width:620px){.field-grid{grid-template-columns:1fr}.field-card{grid-template-columns:1fr}.field-actions{grid-column:1}}</style><style>dialog.bio-nexus-dialog.payment-method-dialog{width:min(1100px,calc(100vw - 32px))!important;max-height:calc(100dvh - 32px)!important}</style>
